import * as Parchment from 'parchment';
import { describe, expect, test, vitest } from 'vitest';
import Quill, { expandConfig } from '../../../src/core/quill.js';
import createRegistryWithFormats from '../../../src/core/utils/createRegistryWithFormats.js';
import { normalizeHTML } from '../__helpers__/utils.js';

const createContainer = (html = '') => {
  const container = document.createElement('div');
  container.innerHTML = normalizeHTML(html);
  document.body.appendChild(container);
  return container;
};

describe('createRegistryWithFormats', () => {
  test('registers core blots only when formats is null', () => {
    const sourceRegistry = new Parchment.Registry();
    // Register core blots in source
    sourceRegistry.register(Parchment);
    const debug = { error: vitest.fn() };
    const registry = createRegistryWithFormats(null, sourceRegistry, debug);
    // Core blots should be present
    expect(registry.query('block', Parchment.Scope.BLOT)).toBeTruthy();
    expect(registry.query('text', Parchment.Scope.BLOT)).toBeTruthy();
    expect(registry.query('scroll', Parchment.Scope.BLOT)).toBeTruthy();
    expect(debug.error).not.toHaveBeenCalled();
  });

  test('registers core blots when formats is empty array', () => {
    const sourceRegistry = new Parchment.Registry();
    sourceRegistry.register(Parchment);
    const debug = { error: vitest.fn() };
    const registry = createRegistryWithFormats([], sourceRegistry, debug);
    expect(registry.query('block', Parchment.Scope.BLOT)).toBeTruthy();
    expect(debug.error).not.toHaveBeenCalled();
  });

  test('skips unknown format names', () => {
    const sourceRegistry = new Parchment.Registry();
    const debug = { error: vitest.fn() };
    const registry = createRegistryWithFormats(['nonexistent-format'], sourceRegistry, debug);
    expect(registry.query('nonexistent-format', Parchment.Scope.BLOT)).toBeNull();
    expect(debug.error).toHaveBeenCalledWith(expect.stringContaining('nonexistent-format'));
  });

  test('detects cycles in required containers', () => {
    const sourceRegistry = new Parchment.Registry();
    const debug = { error: vitest.fn() };

    // Create a cyclic blot definition
    class CyclicBlot extends Parchment.ScrollBlot {
      static blotName = 'cyclic';
      static tagName = 'DIV';
      static requiredContainer = CyclicBlot;
    }
    sourceRegistry.register(CyclicBlot);

    const registry = createRegistryWithFormats(['cyclic'], sourceRegistry, debug);
    expect(debug.error).toHaveBeenCalledWith(expect.stringContaining('Cycle detected'));
  });

  test('returns a new Parchment Registry', () => {
    const sourceRegistry = new Parchment.Registry();
    const debug = { error: vitest.fn() };
    const registry = createRegistryWithFormats(null, sourceRegistry, debug);
    expect(registry).toBeInstanceOf(Parchment.Registry);
  });
});

describe('formats option in Quill configuration', () => {
  test('creates editor with only specified formats plus core blots', () => {
    const container = createContainer();
    const quill = new Quill(container, {
      formats: ['bold', 'italic'],
    });
    // Core blots should exist
    expect(quill.scroll.query('block', Parchment.Scope.BLOT)).toBeTruthy();
    expect(quill.scroll.query('text', Parchment.Scope.BLOT)).toBeTruthy();
    expect(quill.scroll.query('scroll', Parchment.Scope.BLOT)).toBeTruthy();
    // Bold and italic should exist
    expect(quill.scroll.query('bold', Parchment.Scope.BLOT)).toBeTruthy();
    expect(quill.scroll.query('italic', Parchment.Scope.BLOT)).toBeTruthy();
  });

  test('skips unknown format names', () => {
    const container = createContainer();
    const quill = new Quill(container, {
      formats: ['bold', 'fake-format'],
    });
    expect(quill.scroll.query('bold', Parchment.Scope.BLOT)).toBeTruthy();
    expect(quill.scroll.query('fake-format', Parchment.Scope.BLOT)).toBeNull();
  });

  test('includes required containers recursively', () => {
    const container = createContainer();
    const quill = new Quill(container, {
      formats: ['list'],
    });
    // list-item requires list-container, so list-container should be present
    expect(quill.scroll.query('list', Parchment.Scope.BLOT)).toBeTruthy();
    expect(quill.scroll.query('list-container', Parchment.Scope.BLOT)).toBeTruthy();
  });

  test('explicit registry option takes precedence over formats', () => {
    const customRegistry = new Parchment.Registry();
    const container = createContainer();
    // Register something in the custom registry
